@Test
    public void shouldTestEqualityBasedOnTokenAndSecret_oe() {
        final Token expected = new OAuth1AccessToken("access", "secret");
        final Token actual = new OAuth1AccessToken("access", "secret");

        assertEquals(expected, actual);
