@Test
    public void testCRLFMultipartPayload_oe() throws IOException {
        final MultipartPayload mP = new MultipartPayload("simple-boundary");
        mP.addBodyPart(new ByteArrayBodyPartPayload("It does NOT end with a linebreak.".getBytes()));
        mP.addBodyPart(new ByteArrayBodyPartPayload("It does end with a \r linebreak.".getBytes()));
        mP.addBodyPart(new ByteArrayBodyPartPayload("It does end with a \n linebreak.
".getBytes()));
        mP.addBodyPart(new ByteArrayBodyPartPayload("It does end with a \r\n linebreak.
".getBytes()));
        mP.addBodyPart(new ByteArrayBodyPartPayload("the last one".getBytes()));

        final StringBuilder headersString = new StringBuilder();
        for (Map.Entry<String, String> header : mP.getHeaders().entrySet()) {
            headersString.append(header.getKey())
                    .append(": ")
                    .append(header.getValue())
                    .append("
");
        }

        assertEquals("Content-Type: multipart/form-data; boundary="simple-boundary"
", headersString.toString());

        assertEquals("--simple-boundary
" + "
" + "It does NOT end with a linebreak." + "
--simple-boundary
" + "
" + "It does end with a \r linebreak." + "
--simple-boundary
" + "
" + "It does end with a \n linebreak.
" + "
--simple-boundary
" + "
" + "It does end with a \r\n linebreak.
" + "
--simple-boundary
" + "
" + "the last one" + "
--simple-boundary--",MultipartUtils.getPayload(mP).toString());
    }
